// Generated by Faultline from a verified, minimized counterexample.
// Failed signup wipes the typed email and name instead of preserving them
// Attribution: error-path bug: needs the failing request (without it 0/2 control runs failed)
// This test asserts the CORRECT behaviour: it fails while the bug exists and passes once it is fixed.
import { test, expect } from '@playwright/test';
test.use({ serviceWorkers: 'block' });

const TARGET = process.env.FAULTLINE_TARGET ?? "http://127.0.0.1:51827/demo/newsletter.html?mode=fixed";

test("faultline: Failed signup wipes the typed email and name instead of preserving them", async ({ page }) => {
  const origin = new URL(TARGET).origin;
  const requests: { method: string; path: string }[] = [];
  const pageErrors: string[] = [];
  const isApi = (req: any) => ['fetch', 'xhr'].includes(req.resourceType()) && new URL(req.url()).origin === origin;
  page.on('request', (req) => { if (isApi(req)) requests.push({ method: req.method(), path: new URL(req.url()).pathname }); });
  page.on('pageerror', (error) => pageErrors.push(String(error)));
  const seen = [0];
  await page.route((u) => u.origin === origin, async (route) => {
    const req = route.request();
    if (!isApi(req)) return route.continue();
    const r = { method: req.method(), path: new URL(req.url()).pathname };
    // Answer the 1st POST * request with HTTP 500
    if (r.method === "POST") {
      seen[0] += 1;
      if (seen[0] === 1) return route.fulfill({ status: 500, contentType: 'application/json', body: '{"error":"injected by Faultline"}' });
    }
    return route.continue();
  });
  await page.goto(TARGET);
  await page.waitForTimeout(250);
  // Click "Get the newsletter"
  await page.getByTestId("open-signup").click();
  await page.waitForTimeout(120); // human-like pacing, same as Faultline's executor
  // Enter "ada@example.com" into "Work email"
  if (await page.getByTestId("signup-email").evaluate(el => el instanceof HTMLInputElement && el.type === 'password')) throw new Error('Refusing to type into a password field');
  await page.getByTestId("signup-email").fill("ada@example.com");
  await page.waitForTimeout(120); // human-like pacing, same as Faultline's executor
  // Enter "Ada" into "First name"
  if (await page.getByTestId("signup-name").evaluate(el => el instanceof HTMLInputElement && el.type === 'password')) throw new Error('Refusing to type into a password field');
  await page.getByTestId("signup-name").fill("Ada");
  await page.waitForTimeout(120); // human-like pacing, same as Faultline's executor
  // Click "Sign me up"
  await page.getByTestId("signup-submit").click();
  await page.waitForTimeout(120); // human-like pacing, same as Faultline's executor
  await page.waitForTimeout(450);
  // Invariant: "Work email" still holds "ada@example.com"
  await expect(page.getByTestId("signup-email")).toHaveValue("ada@example.com", { timeout: 1000 });
  // Invariant: "First name" still holds "Ada"
  await expect(page.getByTestId("signup-name")).toHaveValue("Ada", { timeout: 1000 });
});
